package localchat;
import java.awt.*;import java.nio.file.*;import java.time.YearMonth;import java.util.*;import java.util.List;import javax.swing.*;
public final class QueueNotificationsTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static void waitRequests(FeatureTest.Server server,int count)throws Exception{for(int i=0;i<500;i++){if(server.requests.size()>=count)return;Thread.sleep(20);}throw new AssertionError("Missing queued request");}
 static void waitScan(LocalChat app)throws Exception{for(int n=0;n<200;n++){boolean[] scanning={true};FeatureTest.edt(()->scanning[0]=FeatureTest.field(app,"hotfolderScanning"));if(!scanning[0])return;Thread.sleep(20);}throw new AssertionError("Hotfolder scan timeout");}
 public static void main(String[] args)throws Exception{
  Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");
  var state=new Conversations.State();state.queue.add(MessageQueue.entry("pending",List.of("fixture.pdf"),true));var loaded=Conversations.State.fromJson(state.toJson(),0);check(loaded.queue.size()==1&&loaded.queuePaused&&loaded.queue.get(0).attachments().equals(List.of("fixture.pdf")),"restart retains pending refs but never starts automatically");
  var monthly=new MonthlyCatalogues(home.resolve("month.json"));Path chats=home.resolve("chats");var draft=new Conversations.State();check(monthly.ensure(YearMonth.of(2026,10),chats,home.toString(),draft),"first local monthly notice creates a draft");check(!monthly.ensure(YearMonth.of(2026,10),chats,home.toString(),new Conversations.State())&&Conversations.list(chats).size()==1,"same month never repeats");check(monthly.ensure(YearMonth.of(2026,11),chats,home.toString(),new Conversations.State())&&Conversations.list(chats).stream().allMatch(c->c.state().unread&&c.messages().isEmpty()),"new month creates unread draft without API messages");
  try(var server=new FeatureTest.Server()){
   LocalChat[] app={null};Path a=home.resolve("root-a"),b=home.resolve("root-b");Files.createDirectories(a.resolve("123456"));Files.createDirectories(b.resolve("654321"));Files.writeString(a.resolve("123456/email.msg"),"fixture email");Files.writeString(b.resolve("654321/email.msg"),"other fixture");FeatureTest.edt(()->{app[0]=AttachmentTest.window(home.resolve("watcher"),server.url());Properties prefs=FeatureTest.field(app[0],"config");prefs.setProperty("hotfolder.enabled","true");prefs.setProperty("hotfolder.path",home.resolve("WRONG-LEGACY-ROOT").toString());FeatureTest.<JTextField>field(app[0],"workDirField").setText(a.toString());FeatureTest.call(app[0],"scanHotfolder",new Class<?>[]{});});waitScan(app[0]);check(Json.str(Json.parse(Files.readString(home.resolve("watcher/hotfolder.json"))),"root").equals(a.toRealPath().toString()),"watcher follows selected work folder rather than legacy configured path");FeatureTest.edt(()->{FeatureTest.<JTextField>field(app[0],"workDirField").setText(b.toString());FeatureTest.call(app[0],"scanHotfolder",new Class<?>[]{});});waitScan(app[0]);check(Json.str(Json.parse(Files.readString(home.resolve("watcher/hotfolder.json"))),"root").equals(b.toRealPath().toString()),"changing selected work folder moves monitoring with a new baseline");check(server.requests.isEmpty(),"monitoring never invokes the model");FeatureTest.edt(()->app[0].dispose());
  }
  try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("First",10,2)),FeatureTest.json(FeatureTest.answer("Second",20,2)),FeatureTest.json(FeatureTest.answer("Third",30,2)))){
   server.delayMillis=300;LocalChat[] app={null};Path file=home.resolve("drop.pdf");Files.writeString(file,"synthetic reference");
   FeatureTest.edt(()->{app[0]=AttachmentTest.window(home.resolve("app"),server.url());app[0].setSize(1400,1000);app[0].addNotify();app[0].validate();AttachmentTest.input(app[0]).setText("first");FeatureTest.call(app[0],"send",new Class<?>[]{});});waitRequests(server,1);
   FeatureTest.edt(()->{check(FeatureTest.<JButton>field(app[0],"sendButton").isEnabled(),"send remains enabled while busy");JTextPane transcript=FeatureTest.field(app[0],"transcript");JViewport viewport=(JViewport)SwingUtilities.getAncestorOfClass(JViewport.class,transcript);check(viewport.getTransferHandler()!=null&&viewport.getTransferHandler().importData(viewport,AttachmentTest.files(file)),"blank chat viewport accepts Explorer file drop while busy");AttachmentTest.input(app[0]).setText("second");FeatureTest.call(app[0],"send",new Class<?>[]{});AttachmentTest.input(app[0]).setText("third");FeatureTest.call(app[0],"send",new Class<?>[]{});check(server.requests.size()==1&&AttachmentTest.state(app[0]).queue.size()==2&&AttachmentTest.input(app[0]).getText().isEmpty(),"explicit sends queue messages with no parallel inference");check(AttachmentTest.state(app[0]).queue.get(0).attachments().size()==1&&AttachmentTest.state(app[0]).queue.get(1).attachments().isEmpty(),"attachment stays with its queued message");check(FeatureTest.<WorkspacePanel>field(app[0],"workspace").notifications.getParent()==FeatureTest.<JPanel>field(app[0],"notificationSlot"),"bell is in the top-right appearance row");});
   waitRequests(server,3);FeatureTest.idle(app[0]);FeatureTest.edt(()->{check(AttachmentTest.state(app[0]).queue.isEmpty(),"FIFO queue drains after successful turns");List<String> users=NormalModeTest.history(app[0]).stream().filter(m->m.role.equals("user")).map(m->m.content).toList();check(users.size()==3&&users.get(0).equals("first")&&users.get(1).startsWith("second")&&users.get(1).contains(Json.write(List.of(file.toRealPath().toString())))&&users.get(2).equals("third"),"history and API order preserve exact queued text and file refs");app[0].dispose();});
  }
  try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("late",10,2)))){
   server.delayMillis=800;server.cancellationExpected=true;LocalChat[] app={null};FeatureTest.edt(()->{app[0]=AttachmentTest.window(home.resolve("stop"),server.url());AttachmentTest.input(app[0]).setText("first");FeatureTest.call(app[0],"send",new Class<?>[]{});});waitRequests(server,1);FeatureTest.edt(()->{AttachmentTest.input(app[0]).setText("pending after Stop");FeatureTest.call(app[0],"send",new Class<?>[]{});FeatureTest.call(app[0],"stop",new Class<?>[]{});check(AttachmentTest.state(app[0]).queuePaused&&AttachmentTest.state(app[0]).queue.size()==1,"Stop preserves and pauses queued messages");});Thread.sleep(150);check(server.requests.size()==1,"Stop never starts another request");FeatureTest.edt(()->app[0].dispose());
  }finally{FeatureTest.edt(()->{for(Window w:Window.getWindows())w.dispose();});}
  System.out.println("PASS: "+checks+" queue/monthly/drop integration checks");System.exit(0);
 }
}
